using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// --- Options with the default reflection-based resolver ---
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1) GetTypeInfo<T>() — returns JsonTypeInfo<T> directly, no cast needed
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person>  →  Type = {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Ada", 36), personInfo);
Console.WriteLine($"  Serialised: {json}");

// 2) TryGetTypeInfo<T>() — probe without throwing
//    Person is resolvable, so this returns true:
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? found))
    Console.WriteLine($"TryGetTypeInfo<Person>  →  resolved ({found!.Type.Name})");
else
    Console.WriteLine("TryGetTypeInfo<Person>  →  not resolved");

//    Now use a custom resolver that only knows about Person.
//    Asking for int should return false instead of throwing.
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new PersonOnlyResolver()
};

if (limited.TryGetTypeInfo<int>(out JsonTypeInfo<int>? intInfo))
    Console.WriteLine($"TryGetTypeInfo<int>    →  resolved ({intInfo!.Type.Name})");
else
    Console.WriteLine("TryGetTypeInfo<int>    →  not resolved (no exception thrown)");

// --- helpers ---
public record Person(string Name, int Age);

/// A resolver that only provides metadata for Person.
file sealed class PersonOnlyResolver : IJsonTypeInfoResolver
{
    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options)
    {
        if (type == typeof(Person))
            return JsonMetadataServices.CreateObjectInfo<Person>(options, new JsonObjectInfoValues<Person>());
        return null;           // unknown type → resolver returns null
    }
}

